const now = new Date();
const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const month = months[now.getMonth()];
const year  = now.getFullYear();
const seasonMap = { December:'Winter',January:'Winter',February:'Winter', March:'Spring',April:'Spring',May:'Spring', June:'Summer',July:'Summer',August:'Summer', September:'Autumn',October:'Autumn',November:'Autumn' };
const season = seasonMap[month];

const systemPrompt = `You are a Pinterest trend expert for women and girls aged 16-35. Identify the most engaging, currently trending Pinterest topics for ${month} ${year} (${season} season). Focus on: fashion, beauty, lifestyle, motivational quotes, wellness, DIY, home decor, food & recipes, travel aesthetics. Return ONLY valid JSON, no extra text.`;

const userPrompt = `Generate 10 trending Pinterest topics for girls/women in ${month} ${year}.\nEach must be specific and have high Pinterest engagement.\nReturn as JSON array: [{"topic":"...","category":"fashion|beauty|lifestyle|quotes|diy|wellness|food|travel","keywords":["kw1","kw2","kw3"]}]`;

return [{ json: {
  month, year, season,
  requestBody: { model:'gpt-4o-mini', messages:[
    { role:'system', content: systemPrompt },
    { role:'user',   content: userPrompt  }
  ], temperature: 0.85, max_tokens: 1500 }
}}];

const raw = $input.first().json.choices[0].message.content;
let trends = [];
try { trends = JSON.parse(raw); }
catch(e) { const m = raw.match(/\[([\s\S]*?)\]/); if(m) trends = JSON.parse('['+m[1]+']'); }

const ts = Date.now();
return trends.map((t, i) => ({ json: {
  id:          `TRD_${ts}_${i}`,
  trend_topic: t.topic,
  category:    t.category || 'lifestyle',
  keywords:    (t.keywords || []).join(', '),
  source:      'openai',
  score:       (Math.floor(Math.random()*3)+7).toString(),
  date_found:  new Date().toISOString().split('T')[0],
  used:        'no'
}}));

const newTrends = $('📋 Parse Trends').all();
const existing  = $input.all().map(i => (i.json.trend_topic || '').toLowerCase().trim());
const filtered  = newTrends.filter(item => {
  const t = (item.json.trend_topic || '').toLowerCase().trim();
  return t && !existing.includes(t);
});
console.log(`${newTrends.length} generated, ${filtered.length} new after dedup`);
if (filtered.length === 0) return [{ json: { _skipped: true } }];
return filtered;
